#!/usr/bin/env python3
"""Rebuild the attributed preview walls and prompt pages from data/videos.json."""
import json, pathlib, html
ROOT=pathlib.Path(__file__).resolve().parents[1]
VIDEOS=json.loads((ROOT/'data/videos.json').read_text())
CTA='https://skillry.dev/skills?output=video&utm_source=github&utm_medium=readme&utm_campaign=awesome-gemini4-argon-videos'
PAGE='https://skillry.dev/ai-videos/gemini-4-argon?utm_source=github&utm_medium=readme&utm_campaign=awesome-gemini4-argon-videos'
CATEGORIES={'motion':('Motion graphics & animation','动画作品'),'3d':('3D scenes & physics','3D 场景与物理'),'interactive':('Games & interactive experiences','游戏与交互')}
for v in VIDEOS:
    attribution=v.get('creatorCredit',f"{v['author']['name']} (@{v['author']['handle']})")
    prompt=f"```text\n{v['prompt']}\n```\n\nPrompt source: {v['promptSourceUrl']}" if v['prompt'] else 'The creator did not publish an exact prompt in the sources reviewed for this entry. The original post below is a description, **not a reconstructed prompt**.'
    if v['promptStatus']=='verbatim_template':prompt='The author shared this template; the exact filled-in subject/reference image was not provided in the text.\n\n'+prompt
    lines=[f"# {v['title']}",'',f"[![Video preview]({v['posterUrl']})]({v['videoUrl']})",'',f"**[▶ Watch / download the original video]({v['videoUrl']})** · **[Original X post]({v['sourceUrl']})**",'',f"- Author / credit: {attribution}",f"- Duration: {v['duration']:.2f} seconds · {v['width']} × {v['height']}",f"- Prompt status: `{v['promptStatus']}`",'',v.get('note',''),'','## Prompt','',prompt,'','## Original post','',v['originalPost'],'','## Sources & attribution','',f"- [{v['author']['name']}]({v['author']['url']}) — [source post]({v['sourceUrl']})"]
    if v.get('promptAuthor'):lines.append(f"- Prompt author: {v['promptAuthor']} — {v['promptSourceUrl']}")
    if v.get('modelEvidenceUrl'):lines.append(f"- Model attribution context: {v['modelEvidenceUrl']}")
    for x in v.get('relatedSources',[]):lines.append(f"- [{x['label']}]({x['url']})")
    for x in v.get('additionalPosts',[]):lines += ['',f"### Additional post by the creator — [source]({x['url']})",'',x['text']]
    lines += ['','Model attribution follows the creator’s published account; it is not an independent audit of the generation process. Original videos, prompts, and post text remain the property of their creators. See [media rights](../MEDIA-RIGHTS.md).','',f"[Explore AI creative skills on Skillry →]({CTA})",'']
    (ROOT/'prompts'/f"{v['id']}.md").write_text('\n'.join(lines))
for zh in [False,True]:
    lines=['# Awesome Gemini 4 Argon Videos','',('[English](README.md) · 简体中文' if zh else 'English · [简体中文](README.zh-CN.md)'),'',('从 X 收集的 Gemini 4 Argon 创作视频：保留作者、完整原文、公开提示词和原帖链接。' if zh else 'A curated collection of Gemini 4 Argon creations shared on X, with original videos, full post text, creator credits, and publicly shared prompts.'),'',f"**[{'▶ 在 Skillry 浏览视频画廊' if zh else '▶ Explore the video gallery on Skillry'}]({PAGE})** · {'最新的排在最前，持续增加中。' if zh else 'newest first, with a live gallery that keeps growing.'}",'',(f"- **{len(VIDEOS)} 条视频**，来自 {len({v['author']['handle'] for v in VIDEOS})} 个发布账号，**持续增加中**：创作者发布新作品后会陆续收录。" if zh else f"- **{len(VIDEOS)} videos** from {len({v['author']['handle'] for v in VIDEOS})} source accounts, **and growing**: new ones are added as creators post them."),f"- {sum(bool(v['prompt']) for v in VIDEOS)} {'条保留了作者公开的原文提示词或模板；其余条目明确标注未公开，不编造提示词。' if zh else 'entries include a verbatim public prompt or template; other entries explicitly say no exact prompt was found.'}",'- '+('原视频、静态封面和动态预览托管于 Skillry R2 / `media.skillry.dev`。点击预览播放视频，点击标题查看原文和提示词。' if zh else 'Original videos, posters, and animated previews are hosted on Skillry R2 / `media.skillry.dev`. Click a preview to watch; click a title for the post and prompt.'),'- '+('只收录成品作品展示；不收录模型对比、测评讲解、教程、制作过程或软件功能介绍。后续新增视频不超过 2 分钟。' if zh else 'Finished creative work only: no model comparisons, reviews, explainers, tutorials, production walkthroughs, or software feature presentations. New submissions must not exceed 2 minutes.'),'- '+('每次更新都是一轮有边界的采集，不代表 X 全量内容；截止时间按原帖发布时间计算，而不是作品实际生成时间。' if zh else 'Each update is a bounded collection pass, not an exhaustive index of X. The cutoff applies to publication, not when the creator generated the work.'),'',('## 目录' if zh else '## Contents'),'']
    for key,(en,cn) in CATEGORIES.items():lines.append(f"- [{cn if zh else en}](#{key}) ({sum(v['category']==key for v in VIDEOS)})")
    for key,(en,cn) in CATEGORIES.items():
        group=[v for v in VIDEOS if v['category']==key];lines+=['',f'<a id="{key}"></a>',f'## {cn if zh else en}','','<table>']
        for i in range(0,len(group),3):
            cells=[]
            for v in group[i:i+3]:
                cells.append(f'<td width="33%" valign="top"><a href="{v["videoUrl"]}"><img src="{v["previewUrl"]}" alt="{html.escape(v["title"],quote=True)}" width="100%"></a><br><a href="prompts/{v["id"]}.md"><b>{html.escape(v["title"])}</b></a><br><sub><a href="{v["sourceUrl"]}">@{v["author"]["handle"]}</a> · {v["duration"]:.0f}s</sub></td>')
            lines.append('<tr>'+''.join(cells)+'</tr>')
        lines+=['</table>']
    lines+=['',('## 如何使用' if zh else '## How to use'),'','1. '+('点击作品标题，查看完整原文和提示词状态。' if zh else 'Open an entry to read the original post and prompt status.'),'2. '+('仅复制作者公开的 Prompt；没有原文提示词的条目可作为灵感参考。' if zh else 'Copy the public prompt when present. Entries without one are inspiration, not reproducible recipes.'),'3. '+('参考作者注明的工具、素材、模型和工作流；模板中的占位符需要自行填写。' if zh else 'Follow the creator’s stated tools, assets, model, and workflow; fill in template placeholders as needed.'),'',('## 数据与核验' if zh else '## Data & verification'),'','- [`data/videos.json`](data/videos.json) — catalog, prompts, timestamps, hashes, R2 URLs','- [`data/source-posts.json`](data/source-posts.json) — source text and attribution','- [`data/collection.json`](data/collection.json) — collection scope and exclusions','- [`data/verification.json`](data/verification.json) — publication and media verification','',('## 致谢与权利' if zh else '## Credits & rights'),'','All videos, prompts, and quoted post text belong to their respective creators. The repository MIT license applies only to our original tooling and curation structure; it does not relicense third-party content. [Rights and correction/removal policy](MEDIA-RIGHTS.md) · [Contributing](CONTRIBUTING.md)','','This community collection is not affiliated with Google. Skillry links are promotional links from the repository maintainer and do not imply creator endorsement or a verified Argon integration.','',f"[{'探索 Skillry →' if zh else 'Explore Skillry →'}]({CTA})",'']
    (ROOT/('README.zh-CN.md' if zh else 'README.md')).write_text('\n'.join(lines))
print(f'Built {len(VIDEOS)} prompt pages and two README preview walls.')
